        dp.append(row)
    best = [0] * (k + 1)
    best1_val = [neg] * (k + 1)
    best1_idx = [-1] * (k + 1)
    best2_val = [neg] * (k + 1)
    for x in idxs:
        for j in range(k, -1, -1):
